#!/bin/bash\n\n# Script de instalación automática para Banco Bot (Mac/Linux)\n\necho \"\"\necho \"============================================\"\necho \"     BANCO BOT - INSTALACIÓN AUTOMÁTICA\"\necho \"============================================\"\necho \"\"\n\n# Verificar si Git está instalado\nif ! command -v git &> /dev/null; then\n    echo \"❌ Git no está instalado\"\n    echo \"📥 Descárgalo desde: https://git-scm.com/\"\n    exit 1\nfi\n\necho \"✅ Git detectado\"\n\n# Verificar si Node.js está instalado\nif ! command -v node &> /dev/null; then\n    echo \"❌ Node.js no está instalado\"\n    echo \"📥 Descárgalo desde: https://nodejs.org/\"\n    exit 1\nfi\n\necho \"✅ Node.js detectado: $(node -v)\"\n\necho \"\"\necho \"📥 Clonando repositorio...\"\ngit clone https://github.com/andersonperez21062000-sketch/banco-bot.git\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Error al clonar\"\n    exit 1\nfi\n\ncd banco-bot\n\necho \"\"\necho \"📝 Renombrando .env.example a .env...\"\ncp .env.example .env\n\necho \"\"\necho \"⚙️ Instalando dependencias...\"\necho \"Esto puede tardar 1-2 minutos...\"\nnpm install\n\nif [ $? -ne 0 ]; then\n    echo \"❌ Error en la instalación\"\n    exit 1\nfi\n\necho \"\"\necho \"============================================\"\necho \"✅ ¡INSTALACIÓN COMPLETADA!\"\necho \"============================================\"\necho \"\"\necho \"📝 PRÓXIMO PASO:\"\necho \"\"\necho \"1. Abre el archivo .env en esta carpeta\"\necho \"2. Reemplaza: TELEGRAM_BOT_TOKEN=tu_token_aqui\"\necho \"   Con tu token de @BotFather\"\necho \"\"\necho \"3. Guarda el archivo\"\necho \"\"\necho \"4. Ejecuta en terminal: npm start\"\necho \"\"\necho \"✅ ¡Listo!\"\necho \"\"